def reuse_key(request, context):
    # resolve everything first: inputs, upstream outputs, tool and model ids
    blob = canonical_json({"request": resolve(request), "context": context})
    return stable_hash(blob)

def run_node(node, request, context, store):
    key = reuse_key(request, context)
    if key in store:
        return store[key]          # exact match: inherit, no model or tool call
    result = node.execute(request, context)
    store[key] = result
    return result
